`timescale 1ns / 1ps

// =============================================================================
// Module: Gowin rPLL Simulation Stub
// Description:
//   Simulation-only stub for the Gowin rPLL IP on the Tang Nano 20K.
//   Takes the 27 MHz onboard crystal and outputs 25.175 MHz pixel clock.
//   In real hardware, this is generated by Gowin EDA's IP Core Generator.
// =============================================================================

module gowin_rpll (
    input  wire clkin,          // 27 MHz onboard crystal
    output wire clkout,         // 25.175 MHz pixel clock
    output wire lock,           // PLL lock indicator
    output wire clkout_serial   // 126.0 MHz 5x serial clock for HDMI
);

    reg clk_out_reg    = 0;
    reg clk_serial_reg = 0;
    reg lock_reg       = 0;

    assign clkout        = clk_out_reg;
    assign clkout_serial = clk_serial_reg;
    assign lock          = lock_reg;

    // Simulate PLL lock-up time (~200 ns)
    initial begin
        lock_reg = 0;
        #200;
        lock_reg = 1;
    end

    // Generate 25.175 MHz: period = 39.72 ns, half = 19.86 ns
    always #19.86 clk_out_reg = ~clk_out_reg;

    // Generate 126.0 MHz: period = 7.936 ns, half = 3.968 ns
    always #3.968 clk_serial_reg = ~clk_serial_reg;

endmodule
